import { HttpClient } from '@angular/common/http';
import { inject, Injectable } from '@angular/core';
import { Observable } from 'rxjs';
import { RouteAiResponse } from '../interfaces/route-ai.interface';
import { ResponsePaginator } from '../../../shared/interfaces/paginator.interface';

@Injectable({
  providedIn: 'root',
})
export class RouteService {

  private _http = inject(HttpClient)

  /** GET routes generated by AI and request from the user authenticated. */
  getRoutesAiUser(params: {} = {}): Observable<ResponsePaginator<RouteAiResponse>> {
    return this._http.get<ResponsePaginator<RouteAiResponse>>('ai-route', {params})
  }
}
